<?php declare(strict_types=1); $heroActions = [['class' => 'button-white', 'href' => $route('contact'), 'label' => $t('actions.contact')]]; require dirname(__DIR__) . '/page-hero.php'; ?>
<section class="section services-page"><div class="shell"><div class="service-grid"><?php foreach ((array) $t('services.items', []) as $service): ?><article><div class="feature-icon"><?= $icon($service['icon']) ?></div><span><?= $e($service['number']) ?></span><h2><?= $e($service['title']) ?></h2><p><?= $e($service['copy']) ?></p><ul><?php foreach ($service['points'] as $point): ?><li><?= $icon('check') ?><?= $e($point) ?></li><?php endforeach; ?></ul></article><?php endforeach; ?></div></div></section>
<section class="section process"><div class="shell"><div class="section-head"><div><span class="section-label"><?= $e($t('services.process.label')) ?></span><h2><?= $e($t('services.process.title')) ?></h2></div><p><?= $e($t('services.process.copy')) ?></p></div><ol class="process-steps"><?php foreach ((array) $t('services.process.steps', []) as $index => $step): ?><li><b><?= str_pad((string) ($index + 1), 2, '0', STR_PAD_LEFT) ?></b><h3><?= $e($step['title']) ?></h3><p><?= $e($step['copy']) ?></p></li><?php endforeach; ?></ol></div></section>
